fn largest_divisor(n: i8) -> i8 {
    // Start checking from n - 1 down to 1
    for d in (1..n).rev() {
        if n % d == 0 {
            return d; // Return the first divisor found
        }
    }
    // This point should never be reached since n > 1
    unreachable!()
}

